static void Countdown(int n)
{
    if (n == 0)
    {
        Console.WriteLine("Start!");
        return;
    }
    Console.WriteLine(n);
    Countdown(n - 1);
}

Countdown(3);
// Ausgabe:
// 3
// 2
// 1
// Start!

static long Fakultaet(int n)
{
    // Basisfall
    if (n <= 1)
        return 1;
    // Rekursionsschritt
    return n * Fakultaet(n - 1);
}

Console.WriteLine(Fakultaet(5));
// Ausgabe: 120

static void Zeige(int n)
{
    if (n == 0) return;
    Console.WriteLine($"rein {n}");
    Zeige(n - 1);
    Console.WriteLine($"raus {n}");
}

Zeige(2);
// Ausgabe:
// rein 2
// rein 1
// raus 1
// raus 2

