static int Summe(int n)
{
    if (n == 0) return 0;
    return n + Summe(n - 1);
}

Console.WriteLine(Summe(4));

static void F(int n)
{
    if (n > 3) return;
    F(n + 1);
    Console.Write(n);
}

F(1);
